import{_ as s,H as e,f as t,i as n}from"./chunks/framework.CBmkDW73.js";const h=JSON.parse('{"title":"Design（设计）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/skills/design.md","filePath":"zh/skills/design.md"}'),i={name:"zh/skills/design.md"};function l(o,a,p,d,c,r){return e(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="design-设计" tabindex="-1">Design（设计） <a class="header-anchor" href="#design-设计" aria-label="Permalink to &quot;Design（设计）&quot;">​</a></h1><p><strong>Gate：</strong> 用户批准规范前，无代码。</p><p>逐轮提问直到知道要构建什么。提议 2-3 种方案与权衡；推荐一个。然后写规范。</p><h2 id="规范-决策列表" tabindex="-1">规范 = 决策列表 <a class="header-anchor" href="#规范-决策列表" aria-label="Permalink to &quot;规范 = 决策列表&quot;">​</a></h2><p>规范回答此变更的待决问题。典型的有：</p><ul><li>契约 / 接口？</li><li>数据形状？</li><li>失败模式？</li><li>超出范围？</li><li>什么测试证明它？</li><li>架构？</li></ul><p>惯例地写规范。</p><p><strong>无问题 → 无章节</strong>。如果 Risks / Non-goals 为空就不填。</p><p>用声明，不用叙述：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>contract:  &lt;接口&gt;</span></span>
<span class="line"><span>invariant: &lt;什么必须成立&gt;</span></span>
<span class="line"><span>test:      &lt;怎么知道它行&gt;</span></span>
<span class="line"><span>deferred:  &lt;现在不决&gt;</span></span></code></pre></div><p>按路径引用代码；永不粘贴它。</p><p>移交前，仅关闭影响实现的决策：契约、数据、失败、测试。未解决的 <code>Working notes</code> 变成决策、<code>deferred</code>，或问题。</p><h2 id="两层-一文件-docs-staging-specs-yyyy-mm-dd-topic-md" tabindex="-1">两层，一文件：<code>docs/staging/specs/YYYY-MM-DD-&lt;topic&gt;.md</code> <a class="header-anchor" href="#两层-一文件-docs-staging-specs-yyyy-mm-dd-topic-md" aria-label="Permalink to &quot;两层，一文件：\`docs/staging/specs/YYYY-MM-DD-&lt;topic&gt;.md\`&quot;">​</a></h2><ul><li>顶部：决策、契约、不变量（永久）。</li><li><code>## Working notes</code>：草稿、待决问题（<code>ship</code> 时删除）。</li></ul><h2 id="roadmap-范围跨-≥3-个里程碑时" tabindex="-1">Roadmap（范围跨 ≥3 个里程碑时） <a class="header-anchor" href="#roadmap-范围跨-≥3-个里程碑时" aria-label="Permalink to &quot;Roadmap（范围跨 ≥3 个里程碑时）&quot;">​</a></h2><p>大到无法一次性计划所有工作时，加 <code>## Roadmap</code> 到规范：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## Roadmap</span></span>
<span class="line"><span>- [ ] M1: &lt;一句话目标&gt;  ← 现在详细计划</span></span>
<span class="line"><span>- [ ] M2: &lt;一句话目标&gt;  ← stub</span></span>
<span class="line"><span>- [ ] M3: &lt;一句话目标&gt;  ← stub</span></span></code></pre></div><p>标记是必须的。M1 <code>← 现在详细计划</code>；其他都是 <code>← stub</code>。Stub 是意图不是承诺；展开前更新。</p><h2 id="gate" tabindex="-1">Gate <a class="header-anchor" href="#gate" aria-label="Permalink to &quot;Gate&quot;">​</a></h2><p><code>docs/staging/specs/YYYY-MM-DD-&lt;topic&gt;.md</code> 必须存在于磁盘且用户确认。</p><p>两种可能的出口之一：</p><ul><li><strong>→ design</strong>：方向是要解决的问题，→ <code>plan</code> 详细任务。</li><li><strong>→ archive</strong>：方向是知识产物（逆向工程发现、协议规范），直接存档。</li></ul>`,22)])])}const u=s(i,[["render",l]]);export{h as __pageData,u as default};
